// Offline cache for 하나마루. Generated by tools/build.py.
const CACHE = 'hanamaru-20261020150606';
const ASSETS = ["./", "./index.html", "./manifest.webmanifest", "./icon-180.png", "./icon-192.png", "./icon-512.png", "./css/app.css?v=20261020150606", "./js/data-common.js?v=20261020150606", "./js/data-ja.js?v=20261020150606", "./js/data-en.js?v=20261020150606", "./js/data-ja-more.js?v=20261020150606", "./js/data-en-more.js?v=20261020150606", "./js/config.js?v=20261020150606", "./js/app.js?v=20261020150606"];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(ASSETS)));
  self.skipWaiting();
});

const VENDOR = 'hanamaru-vendor-1';   // big on-demand files (Japanese dictionary): kept across app updates

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k !== CACHE && k !== VENDOR && !k.startsWith('hanamaru-voice')).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const u = new URL(req.url);
  if (u.hostname.endsWith('workers.dev')) return;                   // AI server (voice, alerts): the app caches what it needs itself
  const path = u.pathname;
  if (path.endsWith('version.json')) return;                        // always ask the network
  if (path.includes('/js/vendor/')) {                                // dictionary: cache first, in its own cache
    e.respondWith(caches.open(VENDOR).then(c => c.match(req).then(hit => hit || fetch(req).then(res => {
      if (res.ok) c.put(req, res.clone());
      return res;
    }))));
    return;
  }
  if (path.endsWith('/js/config.js')) {                              // settings file: newest first, cache for offline
    e.respondWith(fetch(req).then(res => { const copy = res.clone(); caches.open(CACHE).then(c => c.put(req, copy)); return res; })
      .catch(() => caches.match(req, { ignoreSearch: true })));
    return;
  }
  if (req.mode === 'navigate') {                                    // page: network first (never the HTTP cache), cache when offline
    e.respondWith(fetch(req.url.split('#')[0], { cache: 'no-store', credentials: 'same-origin' }).then(res => {
      const copy = res.clone(); caches.open(CACHE).then(c => c.put('./index.html', copy)); return res;
    }).catch(() => caches.match('./index.html')));
    return;
  }
  e.respondWith(caches.match(req).then(hit => hit || fetch(req).then(res => {   // versioned files: cache first
    if (res.ok || res.type === 'opaque') { const copy = res.clone(); caches.open(CACHE).then(c => c.put(req, copy)); }
    return res;
  })));
});

// 매일 공부 알림 (the server sends one only if today's study isn't done yet)
self.addEventListener('push', e => {
  let d = {};
  try { d = e.data ? e.data.json() : {}; } catch (er) { d = { body: e.data ? e.data.text() : '' }; }
  e.waitUntil(self.registration.showNotification(d.title || '하나마루', {
    body: d.body || '오늘 5분만 공부해요!', icon: 'icon-192.png', badge: 'icon-192.png', tag: 'hanamaru-daily', data: { url: self.registration.scope }
  }));
});
self.addEventListener('notificationclick', e => {
  e.notification.close();
  const scope = self.registration.scope;
  e.waitUntil(self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then(list => {
    for (const c of list) if (c.url.startsWith(scope) && 'focus' in c) return c.focus();
    return self.clients.openWindow(scope + '?from=push');
  }));
});
